// JSON 2 - V1 NotebookLM
const v1 = { titulo: 'Web Essentials: A Arquitetura dos Fundamentos', subtitulo: 'Uma dissecacao tecnica de UI, Semantica e Multimedia por DomisDev', image_prompt: 'Isometric blueprint 3 glowing cubes HTML5 CSS3 MULTIMEDIA' };
// MESCLA - spread operator mantem TUDO, nada vira undefined
const mapaMental = { titulo: v1.titulo, subtitulo: v1.subtitulo, centro: v1.titulo, repo: github, ramos: [ {id:'node01', cor:'verde', titulo:'HTML5 SEMANTICS', subtitulo:'NODE 01 - MARKUP LAYER', filhos:['Estrutura','Semantica','Tags','Acessibilidade']}, {id:'node02', cor:'azul', titulo:'CSS3 LAYOUT', subtitulo:'NODE 02 - STYLE E GRID', filhos:['Layout','Grid','Flexbox','Responsivo']}, {id:'node03', cor:'vermelho', titulo:'MULTIMEDIA API', subtitulo:'NODE 03 - MEDIA STREAM', filhos:['Audio','Video','Stream','API Playback']}, {id:'node04', cor:'roxo', titulo:'DADOS GITHUB', subtitulo:'REPO INFO', filhos:['Linguagem: '+github.language, 'Licenca: '+github.license, 'Stars: '+github.stargazers_count, 'Homepage: '+github.homepage]} ], image_prompt: v1.image_prompt, mermaid: 'mindmap root((Web Essentials)) HTML5 CSS3 MULTIMEDIA GITHUB' };
