const mapa = $input.first().json;
const g = mapa.repo;
const html = '<!DOCTYPE html><html><head><meta charset="utf-8"><title>'+mapa.titulo+'</title><style>body{background:#0a0f1c;color:#fff;font-family:Arial;padding:40px}h1{text-align:center}.centro{background:#fff;color:#000;padding:20px;border-radius:16px;text-align:center;max-width:600px;margin:0 auto}.ramos{display:flex;gap:16px;justify-content:center;margin-top:24px;flex-wrap:wrap}.card{padding:20px;border-radius:16px;width:220px}.verde{background:#14532d}.azul{background:#1e3a8a}.vermelho{background:#7f1d1d}.roxo{background:#4c1d95}</style></head><body><h1>'+mapa.titulo+'</h1><p style="text-align:center">'+mapa.subtitulo+'</p><div class="centro"><b>'+mapa.centro+'</b><br>'+g.description+' | '+g.language+' | '+g.license+'<br><a href="'+g.homepage+'">'+g.homepage+'</a></div><div class="ramos">'+mapa.ramos.map(r=>'<div class="card '+r.cor+'"><h3>'+r.titulo+'</h3><small>'+r.subtitulo+'</small><ul>'+r.filhos.map(f=>'<li>'+f+'</li>').join('')+'</ul></div>').join('')+'</div><p style="text-align:center;margin-top:24px">MAPA MENTAL GERADO NO N8N - by DomisDev - SEM UNDEFINED</p></body></html>';
const binaryData = Buffer.from(html).toString('base64');
return [{ json: mapa, binary: { data: { data: binaryData, mimeType: 'text/html', fileName: 'mapa-mental-tecblog-FIX.html' } } }];
